
(() => {
  'use strict';
  const IMAGES = {"neutral": "data:image/png;base64,", "curious": "data:image/png;base64,", "thinking": "data:image/png;base64,", "wink": "data:image/png;base64,", "sideeye": "data:image/png;base64,", "sleepy": "data:image/png;base64,", "pout": "data:image/png;base64,", "annoyed": "data:image/png;base64,", "surprised": "data:image/png;base64,", "pleading": "data:image/png;base64,", "angry": "data:image/png;base64,", "sad": "data:image/png;base64,", "crying": "data:image/png;base64,", "sick": "data:image/png;base64,", "playful": "data:image/png;base64,"};
  const MANIFEST = {"neutral": {"weight": 9, "minHold": 2400, "maxHold": 4800, "rare": false, "next": ["neutral", "curious", "thinking", "sleepy", "sideeye", "surprised", "playful", "pout", "wink", "pleading"]}, "curious": {"weight": 5, "minHold": 1400, "maxHold": 2800, "rare": false, "next": ["thinking", "neutral", "surprised", "wink"]}, "thinking": {"weight": 5, "minHold": 1500, "maxHold": 2800, "rare": false, "next": ["neutral", "curious", "sideeye", "surprised"]}, "wink": {"weight": 3, "minHold": 1200, "maxHold": 2200, "rare": false, "next": ["neutral", "playful", "curious"]}, "sideeye": {"weight": 4, "minHold": 1400, "maxHold": 2600, "rare": false, "next": ["neutral", "thinking", "annoyed", "pout"]}, "sleepy": {"weight": 4, "minHold": 1600, "maxHold": 3000, "rare": false, "next": ["neutral", "sick", "pout"]}, "pout": {"weight": 3, "minHold": 1300, "maxHold": 2300, "rare": false, "next": ["neutral", "annoyed", "angry"]}, "annoyed": {"weight": 2, "minHold": 1300, "maxHold": 2200, "rare": false, "next": ["neutral", "pout", "angry"]}, "surprised": {"weight": 3, "minHold": 1200, "maxHold": 2200, "rare": false, "next": ["neutral", "curious", "pleading"]}, "pleading": {"weight": 2, "minHold": 1400, "maxHold": 2400, "rare": true, "next": ["sad", "neutral"]}, "sad": {"weight": 2, "minHold": 1400, "maxHold": 2400, "rare": true, "next": ["neutral", "crying"]}, "crying": {"weight": 1, "minHold": 1000, "maxHold": 1700, "rare": true, "next": ["sad", "neutral"]}, "angry": {"weight": 2, "minHold": 1200, "maxHold": 2100, "rare": true, "next": ["neutral", "annoyed"]}, "sick": {"weight": 1, "minHold": 1400, "maxHold": 2300, "rare": true, "next": ["sleepy", "neutral"]}, "playful": {"weight": 2, "minHold": 1100, "maxHold": 2100, "rare": false, "next": ["neutral", "wink", "curious"]}};
  const BLINK = "data:image/png;base64,";
  const REDUCE_PD = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  const FIXED_EXPR = 'neutral'; // 固定表情：保留眨眼與呼吸，不再切換臉部表情

  const PHASE = {
    normal: {
      pool:['neutral','curious','thinking','sideeye','surprised','playful','wink'],
      base:'neutral', min:1900, max:3900
    },
    angry: {
      pool:['annoyed','pout','angry','sideeye'],
      base:'annoyed', min:1150, max:2200
    },
    rage: {
      pool:['angry','annoyed','pout'],
      base:'angry', min:800, max:1500
    },
    cry: {
      pool:['crying','sad','pleading','sleepy'],
      base:'crying', min:1100, max:2100
    }
  };

  const instances = new WeakMap();
  const preloadIds = ['neutral','curious','angry','annoyed','crying','sad','surprised','pout'];
  preloadIds.forEach(id => { try { const im = new Image(); im.src = IMAGES[id]; } catch(_) {} });

  const rand=(a,b)=>Math.floor(a+Math.random()*(b-a));
  const phaseFromClass=(el)=>el.classList.contains('mode-cry')?'cry':el.classList.contains('mode-rage')?'rage':el.classList.contains('mode-angry')?'angry':'normal';

  class PastelDragon {
    constructor(host, kind='battle') {
      this.host=host; this.kind=kind; this.phase=kind==='intro'?'normal':phaseFromClass(host);
      this.active=0; this.current='neutral'; this.transitioning=false; this.reacting=false;
      this.exprTimer=null; this.blinkTimer=null; this.reactionTimer=null;
      this.wasHurt=false; this.wasShield=false;
      host.classList.add('pastel-dragon-mounted');
      host.dataset.pdPhase=this.phase;
      host.innerHTML = `
        <div class="pd-stage" aria-hidden="true">
          <div class="pd-expr on" data-pd-layer="0"><img class="pd-main" alt=""><img class="pd-chest" alt=""><img class="pd-belly" alt=""></div>
          <div class="pd-expr" data-pd-layer="1"><img class="pd-main" alt=""><img class="pd-chest" alt=""><img class="pd-belly" alt=""></div>
          <div class="pd-blink"><img class="pd-blink-eyes" alt=""></div>
        </div>`;
      this.layers=[...host.querySelectorAll('.pd-expr')].map(el=>({
        el, main:el.querySelector('.pd-main'), chest:el.querySelector('.pd-chest'), belly:el.querySelector('.pd-belly')
      }));
      this.blink=host.querySelector('.pd-blink');
      this.blinkImg=host.querySelector('.pd-blink-eyes');
      this.blinkImg.src=BLINK;
      this.current=FIXED_EXPR;
      this.setLayer(this.layers[0],FIXED_EXPR);
      this.setLayer(this.layers[1],FIXED_EXPR);
      // 表情固定；只保留自然眨眼與原有呼吸／戰鬥動態。
      this.scheduleBlink();
    }
    phaseMeta() { return PHASE[this.phase]||PHASE.normal; }
    setLayer(layer,id) {
      const src=IMAGES[id]||IMAGES.neutral;
      layer.main.src=src; layer.chest.src=src; layer.belly.src=src; layer.el.dataset.expr=id;
    }
    pick() {
      const meta=this.phaseMeta(), pool=meta.pool.filter(x=>IMAGES[x]);
      if(!pool.length) return meta.base;
      let next=pool[Math.floor(Math.random()*pool.length)];
      if(next===this.current && pool.length>1 && Math.random()<.72) next=pool[(pool.indexOf(next)+1+Math.floor(Math.random()*(pool.length-1)))%pool.length];
      return next;
    }
    fadeTo(id,duration=rand(240,390),after=null) {
      if(!this.host.isConnected) return;
      if(!IMAGES[id]) id='neutral';
      if(this.transitioning && duration>0) return;
      clearTimeout(this.exprTimer);
      const from=this.layers[this.active], to=this.layers[1-this.active];
      this.setLayer(to,id);
      const d=REDUCE_PD?0:Math.max(0,duration);
      to.el.style.transitionDuration=d+'ms'; from.el.style.transitionDuration=d+'ms';
      this.transitioning=true;
      requestAnimationFrame(()=>{
        to.el.classList.add('on'); from.el.classList.remove('on');
        setTimeout(()=>{
          if(!this.host.isConnected) return;
          this.active=1-this.active; this.current=id; this.transitioning=false;
          if(after) after();
          if(!this.reacting && this.kind!=='intro') this.scheduleExpr();
        },d+24);
      });
    }
    scheduleExpr() {
      clearTimeout(this.exprTimer);
      // 固定表情模式：不進行任何自動表情輪替。
      return;
    }
    blinkNow() {
      if(REDUCE_PD||this.transitioning||!this.host.isConnected||!this.blink) return;
      const a=this.blink.animate(
        [{opacity:0,offset:0},{opacity:1,offset:.28},{opacity:1,offset:.60},{opacity:0,offset:1}],
        {duration:185,easing:'ease-in-out'}
      );
      return a;
    }
    scheduleBlink() {
      clearTimeout(this.blinkTimer);
      if(REDUCE_PD||!this.host.isConnected) return;
      this.blinkTimer=setTimeout(()=>{
        this.blinkNow();
        if(Math.random()<.16) setTimeout(()=>this.blinkNow(),rand(105,185));
        this.scheduleBlink();
      },rand(2200,5200));
    }
    setPhase(phase,force=false) {
      if(!PHASE[phase]) phase='normal';
      if(!force && phase===this.phase) return;
      this.phase=phase; this.host.dataset.pdPhase=phase;
      // 戰鬥階段照常更新，但臉部固定為 neutral，不跟著階段換表情。
      if(this.current!==FIXED_EXPR) {
        this.current=FIXED_EXPR;
        this.setLayer(this.layers[0],FIXED_EXPR);
        this.setLayer(this.layers[1],FIXED_EXPR);
      }
    }
    react(type) {
      if(this.kind==='intro'||!this.host.isConnected) return;
      // 受傷／護盾仍由既有 CSS 動畫呈現，但不更換臉部表情。
      clearTimeout(this.reactionTimer); clearTimeout(this.exprTimer);
      this.reacting=false;
      if(this.current!==FIXED_EXPR) {
        this.current=FIXED_EXPR;
        this.setLayer(this.layers[0],FIXED_EXPR);
        this.setLayer(this.layers[1],FIXED_EXPR);
      }
    }
    syncClass() {
      if(this.kind!=='battle') return;
      const p=phaseFromClass(this.host); if(p!==this.phase) this.setPhase(p);
      const hurt=this.host.classList.contains('hurt'), shield=this.host.classList.contains('shield-hit');
      if(hurt&&!this.wasHurt) this.react('hurt');
      else if(shield&&!this.wasShield) this.react('shield');
      this.wasHurt=hurt; this.wasShield=shield;
    }
  }

  function mount(el) {
    if(!el||instances.has(el)||el.classList.contains('pastel-dragon-mounted')) return;
    const kind=el.classList.contains('di-beast')?'intro':'battle';
    const inst=new PastelDragon(el,kind);
    instances.set(el,inst);
    inst.syncClass();
  }
  function scan(root=document) {
    if(root.nodeType===1 && root.matches?.('#ac-battle .ac-dragon,.dragon-intro .di-beast')) mount(root);
    root.querySelectorAll?.('#ac-battle .ac-dragon,.dragon-intro .di-beast').forEach(mount);
  }

  scan();
  const observer=new MutationObserver(muts=>{
    for(const m of muts) {
      if(m.type==='childList') m.addedNodes.forEach(n=>{ if(n.nodeType===1) scan(n); });
      else if(m.type==='attributes' && m.target?.classList?.contains('pastel-dragon-mounted')) {
        instances.get(m.target)?.syncClass();
      }
    }
  });
  observer.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});
  document.addEventListener('visibilitychange',()=>{
    if(document.hidden) return;
    document.querySelectorAll('.pastel-dragon-mounted').forEach(el=>{
      const inst=instances.get(el); if(inst){ inst.scheduleBlink(); }
    });
  });
  window.PastelDragonBoss={scan};
})();
